const STAR = 'M12 0c.9 6.2 5.8 11.1 12 12-6.2.9-11.1 5.8-12 12-.9-6.2-5.8-11.1-12-12C6.2 11.1 11.1 6.2 12 0z'
const STAR_T = 'translate(3004 -790) scale(10.4167)'

/**
 * @param {'gradient'|'white'|'ink'|'black'} tone  gradient on dark; white on colour or photos; ink on light
 * @param {number} height  px; the width follows the fixed ratio
 */
export function GenieWordmark({ tone = 'gradient', height = 48, className = '', title = 'Genie' }) {
  const id = 'genie' + useId().replace(/[^a-zA-Z0-9]/g, '')
  const word = { gradient: `url(#${id})`, white: '#FFFFFF', ink: GENIE_COLORS.ink, black: '#000000' }[tone]
  const star = { gradient: GENIE_COLORS.gold, white: '#FFFFFF', ink: GENIE_COLORS.pink, black: '#000000' }[tone]
  return (
    <svg className={`genie-wordmark ${className}`.trim()} viewBox={VIEWBOX} height={height} width={Math.round(height * RATIO)}
      role={title ? 'img' : undefined} aria-label={title || undefined} aria-hidden={title ? undefined : true}
      style={{ display: 'block', overflow: 'visible' }}>
      {tone === 'gradient' && (
        <defs>
          <linearGradient id={id} x1="0" y1="0" x2="1" y2="0.18">
            <stop offset="0" stopColor={GENIE_COLORS.gold} /><stop offset=".52" stopColor={GENIE_COLORS.pink} /><stop offset="1" stopColor={GENIE_COLORS.violet} />
          </linearGradient>
        </defs>
      )}
      <path d={WORD} fill={word} />
      <path className="genie-sparkle" transform={STAR_T} d={STAR} fill={star} />
    </svg>
  )
}

/**
 * App lockup: the descriptor word (GOSSIP, WEATHER, PDF…) above the wordmark.
 * Descriptor: IBM Plex Mono 600, uppercase, tracked 0.32em, 22% of the
 * wordmark height, left-aligned with the G.
 */
export function GenieLockup({ descriptor, tone = 'gradient', height = 48, className = '' }) {
  const descColor = { gradient: '#E9F1F8', white: '#FFFFFF', ink: '#111111', black: '#000000' }[tone]
  return (
    <span className={`genie-lockup ${className}`.trim()} role="img" aria-label={`${descriptor} Genie`}
      style={{ display: 'inline-flex', flexDirection: 'column', alignItems: 'flex-start', gap: Math.round(height * 0.05) }}>
      <span aria-hidden="true" style={{
        fontFamily: '"IBM Plex Mono", ui-monospace, monospace', fontWeight: 600, textTransform: 'uppercase',
        letterSpacing: '0.32em', fontSize: Math.max(9, Math.round(height * 0.22)), lineHeight: 1,
        color: descColor, paddingLeft: Math.round(height * 0.04),
      }}>{descriptor}</span>
      <GenieWordmark tone={tone} height={height} title="" />
    </span>
  )
}
